bench( format( '%s::set,get:subtitle', pkg ), function benchmark( b ) {
	var values;
	var v;
	var i;

	values = [
		[ 'foo' ],
		[ 'bar' ],
		[ 'beep' ]
	];
	v = new Title();

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v.subtitle = values[ i % values.length ];
		if ( typeof v.subtitle !== 'object' ) {
			b.fail( 'should return an array of strings' );
		}
	}
	b.toc();
	if ( !isStringArray( v.subtitle ) ) {
		b.fail( 'should return an array of strings' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

