bench( format( '%s:toJSON', pkg ), function benchmark( b ) {
	var values;
	var v;
	var o;
	var i;

	values = [
		[ 'foo' ],
		[ 'bar' ],
		[ 'beep' ]
	];
	v = new Title();

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v.text = values[ i % values.length ];
		o = v.toJSON();
		if ( typeof o !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isPlainObject( o ) ) {
		b.fail( 'should return an object' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
